def preserve_legacy_rules(apps,schema_editor):
    import uuid
    Rule=apps.get_model('pms','ReportingRule')
    Lock=apps.get_model('pms','RuleFamilyLock')
    families={}
    for rule in Rule.objects.order_by('pk').iterator():
        key=families.setdefault(rule.name,uuid.uuid4())
        Rule.objects.filter(pk=rule.pk).update(family_key=key,state='LEGACY')
        Lock.objects.get_or_create(key=key)


